def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """

    class LruCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = OrderedDict()

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = self._make_key(args, kwargs, typed)
                if key in self.cache:
                    # If the key is in the cache, move it to the end of the list
                    # so that it gets moved to the front of the cache on its next access
                    self.cache.move_to_end(key)
                    return self.cache[key]
                else:
                    # If the key is not in the cache, add it to the end of the list
                    # and return the result of the function
                    result = func(*args, **kwargs)
                    self.cache[key] = result
                    self.cache.move_to_end(key)
                    if len(self.cache) > maxsize:
                        # If the cache is full, remove the oldest item
                        self.cache.popitem(last=False)
                    return result
            return wrapper

        def _make_key(self, args, kwargs, typed):
            # if typed is True, we need to create a key that includes the types of the function arguments
            # otherwise, the simple values of the arguments will be enough
            if typed:
                key = (args, tuple(type(arg) for arg in args), frozenset(kwargs.items()))
            else:
                key = (args, frozenset(kwargs.items()))
            return key

    return LruCache(maxsize, typed)

