def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Handle edge case where the input is a single interface or implements spec
    if isinstance(sequence, list) and len(sequence) == 1:
        if isinstance(sequence[0], (DeclarationSpec, ImplementsSpec)):
            return sequence[0]

    # Handle edge case where the output is a single interface or implements spec
    if isinstance(output, (DeclarationSpec, ImplementsSpec)):
        return output

    # Normalize the sequence and expand any tuple or DeclarationSpec
    normalized_sequence = []
    for item in sequence:
        if isinstance(item, tuple):
            # Expand tuples of length 1 containing DeclarationSpecs or ImplementsSpecs
            if len(item) == 1 and isinstance(item[0], (DeclarationSpec, ImplementsSpec)):
                normalized_sequence.append(item[0])
            # Expand tuples of length 2 containing DeclarationSpecs or ImplementsSpecs
            else:
                for subitem in item:
                    if isinstance(subitem, (DeclarationSpec, ImplementsSpec)):
                        normalized_sequence.append(subitem)
        elif isinstance(item, (DeclarationSpec, ImplementsSpec)):
            normalized_sequence.append(item)

    # Normalize the output and expand any single interface or implements spec
    if output is not None:
        if isinstance(output, (DeclarationSpec, ImplementsSpec)):
            normalized_output = output
        else:
            raise ValueError("Invalid output argument provided")
    else:
        normalized_output = None

    return normalized_sequence, normalized_output

