def format(sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    :param sql: The SQL query
    :type sql: str or bytes
    :param params: The set of in-style parameters
    :type params: dict or list
    :return: The formatted SQL query and the set of converted out-style parameters
    :rtype: tuple
    """
    if not isinstance(params, dict) and not isinstance(params, list):
        raise ValueError("The params must be either a dict or a list")

    if isinstance(params, dict):
        if self.in_style == "ordinal":
            raise ValueError("The params should not be a dict when the in_style is ordinal")

        out_params = {}
        for name, value in params.items():
            out_params[name] = value

        sql = sql[:]
        for name in out_params:
            sql = sql.replace(f"?{name}", f"@{name}")
    else:
        if self.in_style == "named":
            raise ValueError("The params should not be a list when the in_style is named")

        out_params = []
        for i, value in enumerate(params):
            out_params.append((i + 1, value))

        sql = sql[:]
        for i, value in out_params:
            sql = sql.replace(f"?{i}", f"@{i}")

    return (sql, tuple(out_params))

