    # step 5: iterate over many_params and format each set of parameters
    for i, params in enumerate(many_params):
        # check if the current set of parameters is a mapping
        if isinstance(params, Mapping):
            # create a new dictionary to store the formatted parameters
            formatted_params = {}

            # iterate over the parameters and format them
            for key, value in params.items():
                if not isinstance(key, str) and not isinstance(key, int):
                    raise ValueError(f"keys in each set of many params must be strings or integers, but got {type(key)} at index {i}")

                formatted_params[key] = value

            # add the formatted set of parameters to the list
            out_params.append(formatted_params)

        # check if the current set of parameters is a sequence
        elif isinstance(params, Sequence):
            # create a new list to store the formatted parameters
