    """
    Validate OCFL object at path or pyfs root.

    :return: True if valid (warnings permitted), False otherwise.
    """

    if not self.fs.has_permissions(path):
        raise PermissionError("Insufficient permissions to validate object")

    try:
        obj_info = self.get_object_info(path)
    except ObjectNotFoundError:
        raise ValueError(f"Object at path {path} not found")

    if not obj_info["is_dir"]:
        raise ValueError(f"Path {path} is not a directory")

    try:
        profile = obj_info["profile"]
    except KeyError:
        raise ValueError(f"Profile not specified for object at path {path}")

    if profile != "http://localhost/ocfl/1.0/profiles/versioning":
        raise ValueError(f"Profile {profile} not recognized")

    try:
        digest_algorithm = obj_info["digest_algorithm"]
    except KeyError:
        raise ValueError(f"Digest algorithm not specified for object at path {path}")

    if digest_algorithm not in ["md5", "sha1", "sha256", "sha512"]:
        raise ValueError(f"Digest algorithm {digest_algorithm} not recognized")

    try:
        legacy_root = obj_info["legacy_root"]
    except KeyError:
        raise ValueError(f"Legacy root not specified for object at path {path}")

    if legacy_root is not None and not self.fs.is_dir(legacy_root):
        raise ValueError(f"Legacy root path {legacy_root} not a directory")

    try:
        version = obj_info["version"]
    except KeyError:
        raise ValueError(f"Version not specified for object at path {path}")

    if version not in ["1.0", "2.0"]:
        raise ValueError(f"Version {version} not recognized")

    valid = True
    for item in obj_info["items"]:
        if "object" in item:
            valid &= self.validate(os.path.join(path, item["filename"]))
        else:
            valid &= self.validate_file(os.path.join(path, item["filename"]))

    return valid

