def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Calls the given command(s).

    Args:
        commands (List[str]): A list of commands to be executed.
        args (List[str]): A list of string arguments to be passed to the commands.
        cwd (Optional[str]): The working directory to run the command in.
        verbose (bool): Whether to print the output of the command.
        hide_stderr (bool): Whether to hide the error messages.
        env (Optional[Dict[str, str]]): A dictionary of environment variables to be passed to the command.

    Returns:
        tuple(str, int): The output of the command and the return code.
    """

    # Make sure the inputs are of the correct type and value
    if not isinstance(commands, list) or not isinstance(args, list):
        raise ValueError(f"commands and args must be lists, got {type(commands)} and {type(args)} instead.")

    if cwd is not None and not isinstance(cwd, str):
        raise ValueError(f"cwd must be a string or None, got {type(cwd)} instead.")

    if verbose is not None and not isinstance(verbose, bool):
        raise ValueError(f"verbose must be a boolean or None, got {type(verbose)} instead.")

    if hide_stderr is not None and not isinstance(hide_stderr, bool):
        raise ValueError(f"hide_stderr must be a boolean or None, got {type(hide_stderr)} instead.")

    if env is not None and not isinstance(env, dict):
        raise ValueError(f"env must be a dictionary or None, got {type(env)} instead.")

    # Create the command line
    command_line = commands[0]
    if len(commands) > 1:
        command_line += ' ' + ' '.join(commands[1:])
    if args:
        command_line += ' ' + ' '.join(args)
    if cwd:
        command_line = f"cd {cwd} && {command_line}"
    if env:
        command_line = f"env {' '.join(f'{k}={v}' for k, v in env.items())} {command_line}"

    # Run the command
    process = subprocess.Popen(command_line, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = process.communicate()
    returncode = process.returncode

    # Print the output and error messages
    if verbose:
        if output:
            print(output.decode('utf-8', errors='replace'))
        if error:
            print(error.decode('utf-8', errors='replace'), file=sys.stderr)

    # Return the output and return code
    if returncode == 0:
        return output, returncode
    else:
        raise RuntimeError(f"Command '{command_line}' failed with exit code {returncode}")

# Wrapper function to handle subprocess.Popen exceptions
def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Validate inputs
    if not commands:
        raise ValueError("No command to run")
    if not isinstance(commands, list):
        commands = [commands]
    if args is not None and not isinstance(args, list):
        raise ValueError("args must be a list")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary")

    # Set up the Popen arguments
    popen_args = {"args": commands, "stdin": None, "stdout": None, "stderr": None, "cwd": cwd, "env": env}
    if args is not None:
        popen_args["args"].extend(args)
    if hide_stderr:
        popen_args["stderr"] = subprocess.DEVNULL
    if env is not None:
        popen_args["env"] = env

    # Run the command and get the output
    try:
        output = subprocess.Popen(**popen_args).communicate()[0]
    except subprocess.CalledProcessError as e:
        print(e.output)
        raise RuntimeError("Non-zero exit status") from e

    # Return the output
    return output.decode()

