    """Convert human readable file size to bytes."""
    multiplier = {"K": 1000, "M": 1000000, "G": 1000000000}
    size = size.upper()
    if not size.endswith(tuple(multiplier.keys())):
        raise ValueError("Invalid file size format")
    unit = size[-1]
    value = float(size[:-1])
    return int(value * multiplier[unit])

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """

    if not size:
        raise ValueError("Invalid input size")

    units = {
        "B": 1,
        "K": 1000,
        "M": 1000000,
        "G": 1000000000
    }

    size_unit = size[-1]

    if size_unit not in units:
        raise ValueError("Invalid size unit")

    try:
        size_value = float(size[:-1])
    except ValueError:
        raise ValueError("Invalid input size")

    return int(size_value * units[size_unit])

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes."""

    size_match: Pattern[str] = re.compile(r"^(\d+(?:\.\d+)?)(\w+)$")
    size: float = 0

    match = size_match.match(size.upper())
    if not match:
        raise ValueError(f"Invalid size format: {size}")

    size = float(match.group(1))
    unit = match.group(2)

    if unit == "KB":
        return int(size * 1000)
    elif unit == "MB":
        return int(size * 1000 * 1000)
    elif unit == "GB":
        return int(size * 1000 * 1000 * 1000)
    else:
        raise ValueError(f"Unknown unit: {unit}")

