    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]

    # Create a list of commands and arguments
    command_list = [command + " " + arg for command, arg in zip(commands, args)]

    # Run the command(s)
    try:
        # Create a subprocess and set the environment variables
        if env:
            process = subprocess.Popen(command_list, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        else:
            process = subprocess.Popen(command_list, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        # Get the output and error streams
        output, error = process.communicate()

        # Check if there is an error
        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, command_list)

        # Return the output
        if not hide_stderr:
            return output.decode("utf-8")
        else:
            return output.decode("utf-8"), error.decode("utf-8")

    except subprocess.CalledProcessError as e:
        if verbose:
            print("The following command has been failed:\n{}\nwith error code:\n{}".format(e.cmd, e.returncode))
        return e.output

    except Exception as e:
        if verbose:
            print("An exception has been occurred:", e)
