        # Build command string
        command_string = " ".join(commands)
        if args:
            command_string = " ".join([command_string, " ".join(args)])
        if cwd:
            command_string = "cd {0} && {1}".format(cwd, command_string)
        if hide_stderr:
            command_string += " 2>/dev/null"

        # Run command
        result = subprocess.run(command_string, shell=True, env=env, check=True)
        if verbose:
            print(result.stdout)
        return result
    except Exception as e:
        raise RuntimeError("Error running command: {0}".format(e))
