    """
    Determine the metaclass of a class from its bases and an optional explicit __metaclass__ value.

    :param bases: The bases to determine the metaclass from.
    :param explicit_mc: An optional explicit __metaclass__ value to use.
    :return: The determined metaclass.
    :rtype: type
    """
    if explicit_mc is not None:
        # If an explicit __metaclass__ value was provided, use it.
        return explicit_mc
    elif len(bases) == 1:
        # If only one base was provided, use its type as the metaclass.
        return type(bases[0])
    else:
        # Otherwise, use the usual method of looking up the most derived metaclass.
        bases = list(bases)
        while bases:
            base = bases.pop()
            if hasattr(base, '__class__'):
                return base.__class__
        # If no bases have a __class__ attribute, use type.
        return type

