def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Check if the document is a new-style JSON webfinger
    if document.startswith("{"):
        # Try to parse the JSON document as a dict
        try:
            data = json.loads(document)
        except json.JSONDecodeError:
            # Raise an error if the JSON is invalid
            raise ValueError("Invalid JSON document")
        # Return the data as is
        return data
    # If it's not a new-style JSON webfinger, check if it's an old-style XRD
    elif document.startswith("<XRD"):
        # Try to parse the XRD document as an ElementTree
        try:
            root = etree.fromstring(document.encode("utf-8"))
        except etree.ParseError:
            # Raise an error if the XRD is invalid
            raise ValueError("Invalid XRD document")
        # Extract the ID from the XML document
        id_ = root.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject").text
        # Extract the endpoints from the XML document
        endpoints = [
            (
                endpoint_type,
                endpoint.text
            )
            for endpoint_type, endpoint in root.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}URI")
        ]
        # Return the parsed webfinger object
        return {"id": id_, "endpoints": endpoints}
    else:
        # Raise an error if the document is neither JSON nor XRD
        raise ValueError("Invalid webfinger document")
