@classmethod
def validate_from_content(cls, spec_content):
    """Validates that the spec (YAML) content has all required fields.

    :param spec_content: Content of the spec file.
    :raise IRValidatorException: When mandatory data is missing in the spec file.
    :return: A dictionary with data loaded from the spec file.
    """
    # Check if the spec content is valid
    if not isinstance(spec_content, dict):
        raise IRValidatorException("Invalid spec content: {spec_content}")

    # Check for mandatory fields
    required_fields = ["name", "version", "namespace"]
    for field in required_fields:
        if field not in spec_content:
            raise IRValidatorException(f"Missing mandatory field: {field}")

    # Check for additional fields
    optional_fields = ["title", "description", "license"]
    for field in optional_fields:
        if field not in spec_content:
            continue
        if field in spec_content and not isinstance(spec_content[field], str):
            raise IRValidatorException(f"Invalid value for optional field {field}: {spec_content[field]}")

    # Check for nested child fields
    nested_fields = ["metadata", "spec"]
    for field in nested_fields:
        if field not in spec_content:
            continue
        if not isinstance(spec_content[field], dict):
            raise IRValidatorException(f"Invalid value for nested field {field}: {spec_content[field]}")

    # Check for consistency of nested fields
    nested_required_fields = ["name", "version", "namespace"]
    nested_optional_fields = ["title", "description", "license"]
    for field in nested_required_fields:
        if field not in spec_content["metadata"]:
            raise IRValidatorException(f"Missing mandatory field {field} in nested metadata")
    for field in nested_optional_fields:
        if field in spec_content["metadata"] and not isinstance(spec_content["metadata"][field], str):
            raise IRValidatorException(f"Invalid value for optional field {field} in nested metadata: {spec_content['metadata'][field]}")

    # Return the loaded spec data
    return spec_content
