                # Handle case when include directive is a list of files
                for file in value:
                    if file.endswith(".spec"):
                        included_files.append(file)
            elif isinstance(value, str):
                # Handle case when include directive is a single file
                if value.endswith(".spec"):
                    included_files.append(value)
            else:
                raise ValueError(f"Unsupported include directive: {value}")
        else:
            raise KeyError(f"Unsupported key in include dict: {key}")
    return included_files
