import yaml

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Check if the given path is a dir
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"{plugin_dir} is not a directory")

    # Read the plugin's spec file
    spec_file_path = os.path.join(plugin_dir, "plugin.spec")
    with open(spec_file_path, "r") as f:
        spec = yaml.safe_load(f)

    # Flatten the plugin's spec
    flatten_dict = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f"{key}.{subkey}"] = subvalue
        else:
            flatten_dict[key] = value

    return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # open the json file
    with open(os.path.join(plugin_dir, "plugin.json")) as f:
        plugin_data = json.load(f)

    # initialize an empty dictionary
    flatten_dict = {}

    # iterate over the keys of the plugin data
    for key in plugin_data.keys():
        # if the key is "plugin", add the "plugin" key and its value to the flatten dict
        if key == "plugin":
            flatten_dict["plugin"] = plugin_data[key]

        # iterate over the values of the key
        for value in plugin_data[key]:
            # if the value is a dictionary, recursively call the function
            if isinstance(value, dict):
                # flatten the dictionary
                flatten_dict = {**flatten_dict, **get_plugin_spec_flatten_dict(value)}

            # otherwise, add the key and its value to the flatten dict
            else:
                flatten_dict[key] = value

    return flatten_dict

